# Load all results and identify Pareto frontier
all_results = sandbox_cache["all_combo_results"]

# Remove duplicates (same entities, different order)
seen = set()
unique_results = []
for r in all_results:
    key = tuple(sorted(r["entities"]))
    if key not in seen:
        seen.add(key)
        unique_results.append(r)

# Sort by coverage descending, then provider count ascending
unique_results.sort(key=lambda x: (-x["coverage_pct"], x["relevant_provider_count"]))

print("All unique combinations (sorted by coverage desc, providers asc):")
for i, r in enumerate(unique_results):
    print(f"{i+1}. {' + '.join(r['entities'])}: {r['coverage_pct']:.1f}% ({r['total_covered']}/{r['total_members']}), {r['relevant_provider_count']} providers")

# Identify Pareto frontier
# A combination is Pareto-optimal if no other has both higher coverage AND fewer/equal providers
pareto_frontier = []
for i, r in enumerate(unique_results):
    is_dominated = False
    for j, other in enumerate(unique_results):
        if i == j:
            continue
        # other dominates r if other has higher coverage AND fewer or equal providers
        if other["coverage_pct"] >= r["coverage_pct"] and other["relevant_provider_count"] <= r["relevant_provider_count"]:
            if other["coverage_pct"] > r["coverage_pct"] or other["relevant_provider_count"] < r["relevant_provider_count"]:
                is_dominated = True
                break
    if not is_dominated:
        pareto_frontier.append(r)

print("\n\nPARETO FRONTIER:")
for i, r in enumerate(pareto_frontier):
    print(f"{i+1}. {' + '.join(r['entities'])}: {r['coverage_pct']:.1f}% ({r['total_covered']}/{r['total_members']}), {r['relevant_provider_count']} providers")
    for c in r["details"]:
        print(f"    {c['county']}/{c['specialty']}: {c['coverage_percentage']:.1f}% ({c['members_with_access']}/{c['total_members']})")

sandbox_cache["pareto_frontier"] = pareto_frontier
result = {"pareto_count": len(pareto_frontier)}
